declare
  f jsonb; t text; s jsonb; k text; v_src uuid; v_ok int := 0; v_nivel text;
  v_fichas jsonb := $fichas$[{"familia": "Golden Placenta", "confianza": "media", "targets": ["58e5d59d-95f1-430f-a0e5-f42d81251c01"], "aplica": ["58e5d59d-95f1-430f-a0e5-f42d81251c01"], "secciones": {"resumen": "Según Renovacell, Golden Placenta es un extracto fresco y bioactivo de placenta humana con peso molecular de hasta 300 kDa, obtenido por procesamiento en frío y ultrafiltración, que contiene una mezcla de proteínas, péptidos y factores bioactivos con potencial regenerativo.", "presentacion": "Caja con 20 viales de 2.5 ml cada uno (folleto). En catálogo: \"GOLDEN PLACENTA 2.5 ml\".", "marca": "Renovacell® Tecnologías Antiedad", "caracteristicas": "Según el folleto: extracto de placenta humana de hasta 300 kDa, que incluye proteínas completas, complejos peptídicos y factores de crecimiento asociados (lo distingue de péptidos cosméticos comunes de 5–50 kDa). Describe como componentes típicos de este rango factores de crecimiento (EGF, FGF, TGF-β), péptidos señalizadores, citoquinas moduladoras, aminoácidos esenciales y componentes reguladores de matriz extracelular. Efectos bioactivos que el folleto atribuye: estimular regeneración celular, activar comunicación intercelular, promover reparación de tejidos, modular inflamación, mejorar calidad dérmica y apoyar procesos antiedad a nivel celular.", "diferenciadores": "Según Renovacell: extracción sin calor (método en frío y ultrafiltración) frente a otros extractos de placenta esterilizados a 125 °C o 180 °C; afirma que es \"el único producto en el mundo\" con extractos de placenta puros, frescos y altamente bioactivos (afirmación de la marca, sin evidencia independiente localizada).", "uso_comercial": "El folleto enumera como campos de uso de los extractos placentarios (dependiendo del país y la regulación): medicina regenerativa, investigación biomédica, dermatología avanzada, estética médica (mesoterapia, tópicos de alta gama) y formulaciones antiedad premium.", "composicion": "Por vial: péptidos 1000 µg; cloruro de sodio 20 mg; estabilizantes: cloruro de potasio 0.50 mg, hidrógeno fosfato disódico dodecahidratado 7.55 mg, dihidrogenofosfato de potasio 0.50 mg.", "concentracion": "1000 µg (1000 mcg) de péptidos de placenta por vial de 2.5 ml; peso molecular de hasta 300 kDa.", "tecnologia": "Procesamiento en frío y ultrafiltración, sin aplicación de calor (según Renovacell).", "ficha_tecnica": "Conservar entre +2 °C y +8 °C; no congelar (según el folleto se destruirían los extractos bioactivos). Mantener fuera de la luz solar y del alcance de los niños. Vía de administración: no especificada en el folleto (\"aplicar según la recomendación de su profesional médico tratante\"). Vida útil y registro sanitario: no indicados en las fuentes.", "indicaciones": "El folleto no establece indicaciones aprobadas del producto. Enumera \"principales aplicaciones médicas investigadas\" de extractos placentarios en general (literatura): medicina regenerativa (tejidos blandos, úlceras crónicas, lesiones musculares, quemaduras), dermatología clínica (cicatrices hipertróficas, fotoenvejecimiento severo, dermatitis crónica, reparación post-láser), ginecología (atrofia vaginal; regeneración endometrial en investigación) y hepatoprotección (uso histórico en Asia). Dosis recomendada: \"como coadyuvante al tratamiento ya recomendado\".", "advertencias": "Mantener fuera del alcance de los niños y de la luz del sol. En caso de reacciones alérgicas, suspender inmediatamente y consultar al médico. El propio folleto indica que su uso clínico depende del país y la regulación y \"siempre bajo supervisión médica y con producto certificado\".", "protocolo": "Según el folleto: un vial diario de lunes a viernes durante 4 semanas, o según la recomendación del profesional médico tratante. Abrir el frasco arrancando la tapa en la dirección de la flecha, retirar tapa y tapón de goma, extraer el líquido y aplicar según indicación médica."}, "fuentes": [{"tipo": "renovacell", "referencia": "Folleto Golden Placenta (4 págs., imagen)", "url": "https://www.goldenplacenta.com/web/content/69853", "secciones": ["resumen", "presentacion", "caracteristicas", "diferenciadores", "uso_comercial", "composicion", "concentracion", "tecnologia", "ficha_tecnica", "indicaciones", "advertencias", "protocolo"]}, {"tipo": "renovacell", "referencia": "Folletos digitales — goldenplacenta.com (índice de fichas)", "url": "https://www.goldenplacenta.com/digital-brochures", "secciones": ["presentacion"]}, {"tipo": "renovacell", "referencia": "Renovacell | Tecnologías Anti-Edad — Inicio", "url": "https://www.goldenplacenta.com/inicio", "secciones": ["marca", "fabricante"]}], "especialidades": ["dermatologia", "medicina_estetica"], "relaciones": []}, {"familia": "Ultrafiltrados", "confianza": "media", "targets": ["a3986e55-eeb1-426a-ab2b-9a295be3820f"], "aplica": ["a3986e55-eeb1-426a-ab2b-9a295be3820f", "03b839c2-b094-40e6-85a5-b289e6b501cb", "17a980dd-47bb-4f1d-8045-eda7dd6951cd", "74c3b72e-f938-413e-8479-45e0075c2c26", "60ed8e0b-634b-4260-9ee0-9c9b63e98987", "df88b7f0-c12a-4bc3-9982-d58f323ed348", "2688abc2-293a-474d-8646-23a1a5c9bc07", "76cc56cb-6567-4d53-8330-99ece52bef7d", "b09dfd5d-31e0-44c8-946a-45f7e991280c", "e1f9a301-ae40-4ea5-bc40-21c63394160e", "f9b2695b-74cd-4a98-81ee-4321092c8d62", "1c961bee-0345-4dbf-8d48-e5c9f7842a27", "f08bc3f5-6456-4ca3-b3cf-6e68e4934e47", "ecf4b7e5-b63b-4f71-9126-e95a2876c206", "e2ece653-9734-4486-96cd-7c1ac126beb1", "1b965a38-6512-488e-9d8b-716840cfa192", "c66df1cf-a529-40a6-bad2-17aa56e19719", "8663e890-ea63-42ea-aca2-e699c83b165a", "b922370f-c4eb-415c-aa64-c49072edeacf", "4323f6b6-71b1-46a8-aa0c-39aaaa8553e4"], "secciones": {"resumen": "Según Renovacell, los Ultrafiltrados (UFS) son péptidos nativos órgano-específicos obtenidos por ultrafiltración de tejidos y órganos de conejo, de peso molecular de hasta 10 kDa, presentados para administración por vía oral (mucosa sublingual) con el fin de apoyar la función de sistemas específicos del organismo (nervioso, digestivo, inmunológico, músculo-esquelético y piel).", "presentacion": "Vial (botella) de 2.5 ml de solución; el folleto muestra estuche de varios viales. Variantes por órgano/sistema según catálogo (ACTIVUS, CEREBRI, IMMUNIS, MAGNUS, MOBILIS, OJO, OPTIMUS, REV HOMBRE, REV MUJER, SALUBRE, SANUS, VIVUS, entre otras).", "marca": "Renovacell® Tecnologías Antiedad — línea UFS Ultrafiltrados", "fabricante": "Según el folleto: \"manufacturado bajo los más estrictos estándares de calidad farmacéuticos en la Unión Europea\" (ISO 9001, ISO 14100 [sic], HACCP, GMP). Fabricante específico no nombrado.", "caracteristicas": "Según el folleto: péptidos nativos obtenidos por crio-lisis, filtración multinivel y ultrafiltración final, sin sustancias químicas en la separación; componentes de hasta 10 kDa disueltos en PBS (solución isotónica amortiguada con fosfato). Sin conservadores, azúcar ni gluten; la marca lo describe como apto para personas con diabetes o enfermedad celíaca. Conejos procedentes de granjas bajo control higiénico y veterinario.", "diferenciadores": "Según Renovacell: el principio de organoespecificidad (cada producto aporta péptidos del órgano correspondiente) y la administración oral gracias al bajo peso molecular (≤10,000 Da), lo que, según la marca, permite su absorción por la mucosa oral.", "uso_comercial": "Programas de revitalización por sistema u órgano; el folleto describe el uso típico en ciclos de 20, 40 y hasta 60 viales.", "composicion": "Por vial de 2.5 ml: péptidos 230 µg; cloruro de sodio 20 mg; estabilizantes: cloruro de potasio 0.50 mg, fosfato disódico de hidrógeno dodecahidratado 7.55 mg, fosfato dihidrógeno de potasio 0.50 mg.", "concentracion": "230 µg de péptidos por vial de 2.5 ml (el folleto también dice \"230 mg\" en un apartado; ver por confirmar). Peso molecular ≤10 kDa.", "tecnologia": "Crio-lisis, filtración multinivel y ultrafiltración; producto final suspendido en PBS; control de calidad con sistema HACCP (según Renovacell).", "ficha_tecnica": "Vía: oral/sublingual. Conservar entre +2 °C y +8 °C; no exponer a temperaturas por debajo de 0 °C (la congelación destruiría los péptidos). Mantener fuera del alcance de niños pequeños. Registro: el folleto cita \"aprobado por el Departamento Eslovaco de Salud Pública no. OHVPBK/2873/2012/HT\"; registro en México no indicado. Vida útil: no indicada.", "indicaciones": "Según el folleto, se utilizan para revitalizar o mejorar el funcionamiento de estructuras orgánicas dañadas o con función disminuida por diversas razones o por el envejecimiento fisiológico; no se enumeran indicaciones clínicas aprobadas. El folleto lo menciona como \"suplemento nutricional\".", "advertencias": "Seguir las instrucciones del médico durante el uso. El folleto afirma que no hay riesgo de sobredosis ni efectos secundarios; son afirmaciones de la marca sin datos de seguridad publicados en las fuentes revisadas. Según la marca, fumar o beber alcohol puede afectar negativamente los resultados.", "protocolo": "Según el folleto: una botella al día durante 20 días; periodo óptimo de consumo de 60 días (mínimo 20 viales; uso típico 20, 40 o 60). Abrir jalando la tapa de sellado en dirección de las flechas, vaciar el contenido en una cuchara, colocarlo bajo la lengua 30–40 segundos y tragar. Primeros efectos reportados por la marca a las 3–4 semanas."}, "fuentes": [{"tipo": "renovacell", "referencia": "Folleto Ultrafiltrados Renovacell (6 págs., imagen)", "url": "https://www.goldenplacenta.com/web/content/52036", "secciones": ["resumen", "presentacion", "fabricante", "caracteristicas", "diferenciadores", "uso_comercial", "composicion", "concentracion", "tecnologia", "ficha_tecnica", "indicaciones", "advertencias", "protocolo"]}, {"tipo": "renovacell", "referencia": "Folleto Renovacell ELITE (menciona complementar con Ultrafiltrados)", "url": "https://www.goldenplacenta.com/web/content/70693", "secciones": ["uso_comercial"]}, {"tipo": "renovacell", "referencia": "Folletos digitales — goldenplacenta.com (índice de fichas)", "url": "https://www.goldenplacenta.com/digital-brochures", "secciones": ["presentacion"]}], "especialidades": [], "relaciones": [{"tipo": "complemento", "related_id": "3b8a1d0d-dc84-4d86-95ea-1ee0eb17636b"}]}, {"familia": "Ultrafiltrados · REV HOMBRE", "confianza": "media", "targets": ["f08bc3f5-6456-4ca3-b3cf-6e68e4934e47"], "aplica": ["f08bc3f5-6456-4ca3-b3cf-6e68e4934e47"], "secciones": {"resumen": "Variante de Ultrafiltrados Renovacell (vial 2.5 ml). Aplica todo lo descrito en la ficha de familia Ultrafiltrados.", "presentacion": "Vial de 2.5 ml.", "marca": "Renovacell® Tecnologías Antiedad", "composicion": "Según la tabla 'Tipos de Ultrafiltrados Renovacell' del folleto: Revitalizador de hombre. Concentrados: testículo, placenta, corteza suprarrenal, SNC (cerebro)."}, "fuentes": [{"tipo": "renovacell", "referencia": "Folleto Ultrafiltrados Renovacell, pág. 6 (tabla de tipos)", "url": "https://www.goldenplacenta.com/web/content/52036", "secciones": ["composicion"]}], "especialidades": [], "relaciones": []}, {"familia": "Ultrafiltrados · REV MUJER", "confianza": "media", "targets": ["c66df1cf-a529-40a6-bad2-17aa56e19719"], "aplica": ["c66df1cf-a529-40a6-bad2-17aa56e19719"], "secciones": {"resumen": "Variante de Ultrafiltrados Renovacell (vial 2.5 ml). Aplica todo lo descrito en la ficha de familia Ultrafiltrados.", "presentacion": "Vial de 2.5 ml.", "marca": "Renovacell® Tecnologías Antiedad", "composicion": "Según la tabla 'Tipos de Ultrafiltrados Renovacell' del folleto: Revitalizador de mujer. Concentrados: ovario, placenta, corteza suprarrenal, SNC (cerebro)."}, "fuentes": [{"tipo": "renovacell", "referencia": "Folleto Ultrafiltrados Renovacell, pág. 6 (tabla de tipos)", "url": "https://www.goldenplacenta.com/web/content/52036", "secciones": ["composicion"]}], "especialidades": [], "relaciones": []}, {"familia": "Ultrafiltrados · SANUS", "confianza": "media", "targets": ["76cc56cb-6567-4d53-8330-99ece52bef7d"], "aplica": ["