anza": "media", "targets": ["74c3b72e-f938-413e-8479-45e0075c2c26"], "aplica": ["74c3b72e-f938-413e-8479-45e0075c2c26"], "secciones": {"resumen": "Según Renovacell, Golden V® es un producto de péptidos bioactivos frescos de embriones vegetales combinados con glutatión reducido (GSH), orientado a un efecto antioxidante y revitalizante.", "presentacion": "Caja con 20 viales de 2.5 ml cada uno (folleto). En catálogo: 'ULTRAFILTRADO GOLDEN V 2.5 ml'.", "marca": "Golden V® — Renovacell® Tecnologías Antiedad", "caracteristicas": "Según el folleto, contiene principalmente oligopéptidos (0.5–5 kDa), péptidos señalizadores de bajo peso molecular, péptidos medianos (hasta 10 kDa), factores de crecimiento vegetal, aminoácidos esenciales, metabolitos secundarios, polifenoles antioxidantes, trazas de fitohormonas y enzimas antioxidantes (tipo SOD y catalasa). El folleto aclara que los embriones vegetales no contienen factores de crecimiento humanos y que su acción es indirecta (antioxidante, señalización celular, estimulación redox). Mecanismos reportados in vitro: reducción de ROS, estimulación de fibroblastos, mejora indirecta en síntesis de colágeno, protección frente a estrés oxidativo y modulación inflamatoria.", "diferenciadores": "Según Renovacell: alternativa vegetal a los péptidos animales, con bajo riesgo inmunológico, alta estabilidad, buena compatibilidad dérmica y regulación más sencilla que los extractos animales.", "uso_comercial": "El folleto señala como usos: cosmética avanzada, sueros revitalizantes antiedad, terapia de péptidos vegetales, productos reafirmantes y tratamientos post-procedimiento dermatológico; aplicación clínica potencial en protocolos antioxidantes complementarios, soporte hepático, medicina estética (estrés oxidativo cutáneo) y programas antiedad basados en balance redox; en estética, apoyo en hiperpigmentación (por GSH).", "composicion": "Por vial: péptidos vegetales 1000 µg; cloruro de sodio 20 mg; estabilizantes: cloruro de potasio 0.50 mg, hidrógeno fosfato disódico dodecahidratado 7.55 mg, dihidrogenofosfato de potasio 0.50 mg. El folleto menciona GSH, pero no indica su cantidad.", "concentracion": "1000 µg de péptidos vegetales por vial de 2.5 ml.", "tecnologia": "Extracción acuosa en frío, hidrólisis enzimática controlada, ultrafiltración (ej. ≤5–10 kDa), purificación y estabilización (según el folleto).", "ficha_tecnica": "Conservar entre +2 °C y +8 °C; no congelar. Mantener fuera de la luz solar y del alcance de los niños. Vía: el folleto menciona usos posibles inyectable ('uso médico regulado') y oral, sin definir la vía autorizada del producto. Vida útil y registro sanitario no indicados.", "indicaciones": "Uso como coadyuvante del tratamiento indicado por el médico (según el folleto); no se enumeran indicaciones aprobadas.", "advertencias": "En caso de reacciones alérgicas, suspender inmediatamente y consultar al médico.", "protocolo": "Según el folleto: un vial diario de lunes a viernes durante 4 semanas, o según la recomendación del profesional médico tratante. Abrir arrancando la tapa en dirección de la flecha, retirar tapa y tapón de goma, extraer el líquido y aplicar según indicación médica."}, "fuentes": [{"tipo": "renovacell", "referencia": "Folleto Golden V (5 págs., imagen)", "url": "https://www.goldenplacenta.com/web/content/69854", "secciones": ["resumen", "presentacion", "caracteristicas", "diferenciadores", "uso_comercial", "composicion", "concentracion", "tecnologia", "ficha_tecnica", "indicaciones", "advertencias", "protocolo"]}, {"tipo": "renovacell", "referencia": "Folletos digitales — goldenplacenta.com (índice de fichas)", "url": "https://www.goldenplacenta.com/digital-brochures", "secciones": ["presentacion"]}], "especialidades": ["dermatologia", "medicina_estetica"], "relaciones": []}, {"familia": "Ultrafiltrados · FT EXTRACTS (Fetal Total Extracts)", "confianza": "media", "targets": ["ecf4b7e5-b63b-4f71-9126-e95a2876c206"], "aplica": ["ecf4b7e5-b63b-4f71-9126-e95a2876c206"], "secciones": {"resumen": "Según Renovacell, Fetal Total Extracts son preparaciones biológicas obtenidas de tejidos embriofetales de conejo mediante extracción acuosa, enzimática o hidrolítica y purificadas por ultrafiltración; contienen una mezcla compleja de péptidos, ácidos nucleicos, factores de crecimiento, citoquinas y componentes de matriz extracelular.", "presentacion": "Caja con 20 viales de 2.5 ml (folleto).", "marca": "Renovacell® Tecnologías Antiedad", "caracteristicas": "Según el folleto: mezcla de péptidos bioactivos, fragmentos de ADN/ARN, aminoácidos y cofactores, proteínas estructurales, péptidos señalizadores, factores de crecimiento, componentes de matriz extracelular, citoquinas, nucleótidos. Beneficios descritos según estudios preclínicos: proliferación de fibroblastos, síntesis de colágeno tipo I y III, remodelación de matriz extracelular, efecto cicatrizante, modulación inflamatoria in vitro, actividad antioxidante y efecto trófico celular.", "composicion": "Por vial: péptidos 550 µg; cloruro de sodio 20 mg; estabilizantes: cloruro de potasio 0.50 mg, hidrógeno fosfato disódico dodecahidratado 7.55 mg, dihidrogenofosfato de potasio 0.50 mg.", "concentracion": "550 µg de péptidos por vial de 2.5 ml. El folleto describe el hidrolizado de 10–15 kDa.", "tecnologia": "Ultrafiltración por membranas para seleccionar péptidos según tamaño molecular (según el folleto).", "ficha_tecnica": "Conservar entre +2 °C y +8 °C; no congelar. Mantener fuera de la luz solar y del alcance de los niños. Vía de administración no especificada (\"aplicar según la recomendación de su profesional médico tratante\"). Registro sanitario y vida útil no indicados.", "indicaciones": "Uso como coadyuvante del tratamiento indicado por el médico (según el folleto). El propio folleto advierte que la evidencia clínica robusta es limitada.", "advertencias": "El folleto indica textualmente que 'la evidencia clínica robusta es limitada y su regulación es estrictamente para ensayos y propósitos de investigación'. En caso de reacciones alérgicas, suspender inmediatamente y consultar al médico.", "protocolo": "Según el folleto: un vial diario de lunes a viernes durante 4 semanas, o según el médico tratante."}, "fuentes": [{"tipo": "renovacell", "referencia": "Folleto Fetal Total Extracts (3 págs., imagen)", "url": "https://www.goldenplacenta.com/web/content/70687", "secciones": ["resumen", "presentacion", "caracteristicas", "composicion", "concentracion", "tecnologia", "ficha_tecnica", "indicaciones", "advertencias", "protocolo"]}, {"tipo": "renovacell", "referencia": "Folletos digitales — goldenplacenta.com (índice de fichas)", "url": "https://www.goldenplacenta.com/digital-brochures", "secciones": ["presentacion"]}], "especialidades": [], "relaciones": []}, {"familia": "ELITE", "confianza": "media", "targets": ["3b8a1d0d-dc84-4d86-95ea-1ee0eb17636b"], "aplica": ["e2ce81ee-ebdb-4d29-8fbb-696c8b942d4e", "4e42ea74-ca5e-4042-bd9a-a7404a2bef3c", "36c2e2fe-efc8-422a-b01b-f28e9ef35bcd", "2d453484-2b65-41c0-b93f-49e1d0f25850", "04d4360f-27be-4866-8982-4970123cc9bb", "01f337ab-4cae-4516-a186-dc8d8284271f", "3b8a1d0d-dc84-4d86-95ea-1ee0eb17636b"], "secciones": {"resumen": "Según Renovacell, el Programa de Revitalización ELITE es un tratamiento de extractos celulares ultrafiltrados de alto peso molecular para revitalizar los principales órganos y tejidos; el set reúne 10 extractos celulares de órganos que la marca considera clave en la degeneración celular.", "presentacion": "Según el folleto: set de 10 viales de extractos celulares hidrolizados frescos, puros y refrigerados, para diluir en 5 ml de solución fisiológica; presentaciones Masculino y Femenino. En catálogo: variantes 5 ml 300 kDa (Hombre, Mujer, IMMUNIS, MOBILIS, Ojo, Placenta).", "marca": "Renovacell® Tecnologías Antiedad — ELITE", "caracteristicas": "Según el folleto, se ofrece en dos concentraciones de peso molecular: <300,000 Da y <1,000,000 Da, frente a los ultrafiltrados convencionales (<10,000 Da).", "diferenciadores": "Según Renovacell: mayor peso molecular (<300 kDa / <1,000 kDa) que los ultrafiltrados convencionales; la marca lo presenta como 'el tratamiento más avanzado del mundo en regeneración celular' (afirmación promocional).", "uso_comercial": "Programa de revitalización por sexo (masculino/femenino) con ajuste individual por el médico tratante; en síntomas crónicos el folleto sugiere repetir el tratamiento o complementar con Ultrafiltrados Renovacell.", "composicion": "ELITE Masculino: bazo, cerebro, corazón, cordón umbilical, mix total de órganos, glándula suprarrenal, hígado, placenta, timo y testículo. ELITE Femenino: igual, con ovario en lugar de testículo (según el folleto). Excipientes y cantidad de péptidos por vial: no indicados.", "concentracion": "Peso molecular <300,000 Da o <1,000,000 Da según presentación (el catálogo vende variantes de 300 kDa). Contenido de péptidos por vial no indicado.", "tecnologia": "Extractos celulares ultrafiltrados/hidrolizados frescos, refrigerados (según el folleto).", "ficha_tecnica": "Refrigerado (el folleto dice 'refrigerados'; rango de temperatura no especificado). Reconstitución/dilución en 5 ml de solución fisiológica. Vía de administración no especificada explícitamente. Registro sanitario y vida útil no indicados.", "indicaciones": "El folleto no establece indicaciones aprobadas; plantea como meta que órganos y tejidos funcionen apropiadamente, con asesoría del profesional médico tratante.", "advertencias": "Según el folleto, es bien tolerado, pero pueden presentarse prurito y brotes de picazón alrededor del sitio de aplicación, que suelen manejarse con hielo o cremas refrescantes. El folleto interpreta estas reacciones como activación inmune deseada en pacientes con deficiencia inmune; esta interpretación no está respaldada en las fuentes. Consulte al médico sobre efectos secundarios.", "protocolo": "Según el folleto: tratamiento clásico de 10 aplicaciones durante 2 semanas; el plan puede modificarse según condiciones y requisitos individuales; puede repetirse o complementarse con Ultrafiltrados Renovacell según el médico."}, "fuentes": [{"tipo": "renovacell", "referencia": "Folleto Línea Renovacell ELITE (7 págs.)", "url": "https://www.goldenplacenta.com/web/content/70693", "secciones": ["resumen", "presentacion", "caracteristicas", "diferenciadores", "uso_comercial", "composicion", "concentracion", "tecnologia", "ficha_tecnica", "indicaciones", "advertencias", "protocolo"]}, {"tipo": "renovacell", "referencia": "Folletos digitales — goldenplacenta.com (índice de fichas)", "url": "https://www.goldenplacenta.com/digital-brochures", "secciones": ["presentacion"]}], "especialidades": [], "relaciones": [{"tipo": "complemento", "related_id": "a3986e55-eeb1-426a-ab2b-9a295be3820f"}]}, {"familia": "ELITE · Hombre", "confianza": "media", "targets": ["e2ce81ee-ebdb-4d29-8fbb-696c8b942d4e"], "aplica": ["e2ce81ee-ebdb-4d29-8fbb-696c8b942d4e"], "secciones": {"resumen": "Variante del Programa de Revitalización ELITE. Aplica lo descrito en la ficha de familia ELITE.", "marca": "Renovacell® Tecnologías Antiedad", "composicion": "Según el folleto: Bazo, cerebro, corazón, cordón umbilical, mix total de órganos, glándula suprarrenal, hígado, placenta, timo y testículo (Programa ELITE Masculino)."}, "fuentes": [{"tipo": "renovacell", "referencia": "Folleto Línea Renovacell ELITE", "url": "https://www.goldenplacenta.com/web/content/70693", "secciones": ["composicion"]}], "especialidades": [], "relaciones": []}, {"familia": "ELITE · Mujer", "confianza": "media", "targets": ["2d453484-2b65-41c0-b93f-49e1d0f25850"], "aplica": ["2d453484-2b65-41c0-b93f-49e1d0f25850"], "secciones": {"resumen": "Variante del Programa de Revitalización ELITE. Aplica lo descrito en la ficha de familia ELITE.", "marca": "Renovacell® Tecnologías Antiedad", "composicion": "Según el folleto: Bazo, cerebro, corazón, cordón umbilical, mix total de órganos, glándula suprarrenal, hígado, placenta