, "referencia": "Nano HR replacement cartridges for Hydra Pen H3/H5 (Bigamart)", "url": "https://bigamart.com/product/15pcs-nano-hr-microneedling-pen-replacement-cartridges-needles-for-hydra-pen-h3-h5-serum-applicator-authentic-disposable-replacement-needles-tips-skin-care-accessories-nano-hr-15pcs/", "secciones": ["caracteristicas", "diferenciadores"]}], "especialidades": ["dermatologia", "medicina_estetica"], "relaciones": [{"tipo": "complemento", "related_id": "5d06d155-da32-4494-9cc9-a4cefa654596"}]}, {"familia": "Agujas/cánulas FMC", "confianza": "media", "targets": ["0800d7f4-f8fa-45a8-8783-b2b5f516facd"], "aplica": ["0800d7f4-f8fa-45a8-8783-b2b5f516facd", "6f52735b-a611-4fa0-affa-8f9bbbdca858", "14cca947-f301-4f33-915e-2c52dd38873a", "c07fbb83-120c-4aa4-943c-fefe78dd5e13", "66243b28-1f4d-4891-850d-fd845319abee", "877b3b1c-b5a3-4cb5-a2db-c9a695347464", "768c4b20-e51c-40c5-9a5a-cf4cffdf30fe"], "secciones": {"resumen": "FMC (Fine Micro Cannulae): microcánulas de punta roma para inyección atraumática de rellenos y bioestimuladores, con aguja de pre-punción del mismo calibre en cada blíster.", "presentacion": "Calibres en catálogo: 22G × 50 mm, 22G × 70 mm, 25G × 40 mm, 25G × 50 mm, 27G × 40 mm y 27G × 50 mm. Cada cánula en blíster estéril individual con aguja de pre-punción; el distribuidor británico las vende en cajas de 24.", "marca": "FMC – Fine Micro Cannulae.", "fabricante": "No confirmado. El registro GUDID de FDA lista \"Fine Micro Cannula\" (22G × 50 mm) con Feeltech Co., Ltd. como etiquetador (prefijo GS1 de Corea).", "caracteristicas": "Cánula de acero inoxidable electropulido de pared ultradelgada, punta roma, orificio lateral con borde curvo, superficie pulida y recubierta, marcas de graduación y orientación, conector de policarbonato con rosca (luer-lock).", "diferenciadores": "La pared ultradelgada permite mayor diámetro interno y menor fuerza de extrusión para un calibre dado, según el distribuidor.", "tecnologia": "Microcánula roma para disección atraumática del plano de inyección, con menor riesgo de lesión vascular que la aguja.", "ficha_tecnica": "Estéril, de un solo uso (GUDID). En GUDID figura con código de producto FDA FMI y 510(k) K092831. Registro COFEPRIS por confirmar.", "indicaciones": "Uso con todos los rellenos dérmicos según el distribuidor (aplicación de ácido hialurónico, hidroxiapatita de calcio, ácido poliláctico, etc.).", "advertencias": "Un solo uso; no reesterilizar. El calibre 27G × 50 mm del catálogo no aparece en la lista de medidas FMC del distribuidor (22G/50, 22G/70, 23G/50, 25G/40, 25G/50, 27G/40, 30G/25, 20G/70): confirmar.", "protocolo": "Realizar el punto de entrada con la aguja de pre-punción incluida del mismo calibre e introducir la cánula; técnica según el relleno empleado."}, "fuentes": [{"tipo": "distribuidor", "referencia": "FMC Fine Micro Cannulae (4T Medical, distribuidor exclusivo Reino Unido)", "url": "https://www.4tmedical.com/product/consumables/aesthetic-sundries/fmc-fine-micro-cannulae/", "secciones": ["caracteristicas", "presentacion", "diferenciadores", "indicaciones", "advertencias"]}, {"tipo": "distribuidor", "referencia": "FMC Fine Micro Cannulae 22G 50mm (DD Group)", "url": "https://www.ddgroup.com/facial-aesthetics/cannulas/600046--fmc-fine-micro-cannulae-22g-50mm/", "secciones": ["presentacion"]}, {"tipo": "regulatorio", "referencia": "AccessGUDID – Fine Micro Cannula (Feeltech Co., Ltd.)", "url": "https://accessgudid.nlm.nih.gov/devices/18809407786451", "secciones": ["fabricante", "ficha_tecnica"]}], "especialidades": ["cirugia_plastica", "dermatologia", "medicina_estetica"], "relaciones": [{"tipo": "complemento", "related_id": "90b59637-02a8-402e-afe0-d6100e72f9e0"}, {"tipo": "complemento", "related_id": "75840f69-ad51-4ec3-9c3b-4cb55ceac6b8"}, {"tipo": "complemento", "related_id": "c0110398-bab1-4636-9134-b02eb6a632b4"}, {"tipo": "complemento", "related_id": "e845a3bb-5d42-467a-923a-0998752d47c3"}, {"tipo": "complemento", "related_id": "f5e81e86-212e-4a40-ab08-868c2be840fd"}]}]$fichas$::jsonb;
begin
  for f in select * from jsonb_array_elements(v_fichas) loop
    continue when not exists (select 1 from public.products p, jsonb_array_elements_text(f -> 'aplica') a where p.id = a::uuid);
    -- fuentes de esta ficha
    create temp table if not exists _src (idx int, id uuid, secciones jsonb) on commit drop;
    truncate _src;
    for s in select * from jsonb_array_elements(f -> 'fuentes') loop
      insert into public.cc_knowledge_sources (tipo, referencia, documento_url, version, notas)
      values (s ->> 'tipo', s ->> 'referencia', s ->> 'url', 'investigacion-2026-10', 'Investigación IA 30 oct 2026 · ' || (f ->> 'familia') || ' · confianza ' || coalesce(f ->> 'confianza', '?'))
      on conflict (tipo, referencia, coalesce(version, '')) do nothing;
      insert into _src (idx, id, secciones)
      select (select count(*) from _src), id, s -> 'secciones' from public.cc_knowledge_sources
       where tipo = s ->> 'tipo' and referencia = s ->> 'referencia' and coalesce(version, '') = 'investigacion-2026-10';
    end loop;
    for t in select jsonb_array_elements_text(f -> 'targets') loop
      continue when not exists (select 1 from public.products where id = t::uuid);
      for k in select jsonb_object_keys(f -> 'secciones') loop
        v_nivel := public._cc_nivel_seccion(k);
        continue when v_nivel is null;
        continue when exists (select 1 from public.cc_product_knowledge where product_id = t::uuid and seccion = k and estado = 'draft');
        select id into v_src from _src where secciones ? k order by idx limit 1;
        if v_src is null then select id into v_src from _src order by idx limit 1; end if;
        insert into public.cc_product_knowledge (product_id, seccion, nivel, version, estado, audiencia, contenido, source_id, importado_de)
        values (t::uuid, k, v_nivel,
                coalesce((select max(version) from public.cc_product_knowledge where product_id = t::uuid and seccion = k), 0) + 1,
                'draft', case when v_nivel = 'T0' then 'public' else 'verified' end, f -> 'secciones' ->> k, v_src, 'investigacion-2026-10');
        v_ok := v_ok + 1;
        v_src := null;
      end loop;
    end loop;
    -- especialidades (a todos los productos que cubre la ficha) y relaciones en borrador
    insert into public.cc_producto_especialidad (product_id, especialidad, origen)
    select a::uuid, e, 'fuente' from jsonb_array_elements_text(f -> 'aplica') a, jsonb_array_elements_text(f -> 'especialidades') e
     where exists (select 1 from public.products where id = a::uuid) and exists (select 1 from public.especialidades where clave = e)
    on conflict do nothing;
    insert into public.cc_product_relations (product_id, related_id, tipo, estado, nota)
    select t2::uuid, (r ->> 'related_id')::uuid, r ->> 'tipo', 'draft', 'Sugerida por investigación (oct 2026); revisar'
      from jsonb_array_elements_text(f -> 'targets') t2, jsonb_array_elements(f -> 'relaciones') r
     where exists (select 1 from public.products where id = t2::uuid) and exists (select 1 from public.products where id = (r ->> 'related_id')::uuid)
       and t2::uuid <> (r ->> 'related_id')::uuid
    on conflict do nothing;
  end loop;
  raise notice 'FICHAS: % secciones en borrador', v_ok;
end $carga$;
